int main() {
    char s[100005], t[100005];
    scanf("%s %s", s, t);

    int slen = strlen(s);
    int tlen = strlen(t);

    long long copies = 0;
    int pos = 0;

    for (int k = 0; k < tlen; k++) {
        char c = t[k];
        // Search for c in s[pos..slen-1]
        int found = -1;
        for (int j = pos; j < slen; j++) {
            if (s[j] == c) {
                found = j;
                break;
            }
        }
        if (found == -1) {
            // Try from beginning of next copy
            copies++;
            found = -1;
            for (int j = 0; j < slen; j++) {
                if (s[j] == c) {
                    found = j;
                    break;
                }
            }
            if (found == -1) {
                printf("-1\n");
                return 0;
            }
            pos = found + 1;
        } else {
            pos = found + 1;
        }
        if (pos == slen) {
            copies++;
            pos = 0;
        }
    }

    long long answer = copies * (long long)slen + pos;
    printf("%lld\n", answer);
    return 0;
}

