int main(void) {
    char s[200005], t[200005];
    if (scanf("%200000s %200000s", s, t) != 2) return 0;

    int n = (int)strlen(s);
    int m = (int)strlen(t);

    int cntS[26] = {0};
    for (int i = 0; i < n; i++) cntS[s[i] - 'a']++;

    for (int i = 0; i < m; i++) {
        if (cntS[t[i] - 'a'] == 0) {
            printf("-1\n");
            return 0;
        }
    }

    int *pos[26];
    int sz[26] = {0};
    for (int c = 0; c < 26; c++) pos[c] = (int *)malloc(sizeof(int) * cntS[c]);

    int curCnt[26] = {0};
    for (int i = 0; i < n; i++) {
        int c = s[i] - 'a';
        pos[c][curCnt[c]++] = i;
    }
    for (int c = 0; c < 26; c++) sz[c] = curCnt[c];

    long long ans = 0;      // number of characters consumed
    int cur = -1;           // current position in current copy of s

    for (int i = 0; i < m; i++) {
        int c = t[i] - 'a';
        int l = 0, r = sz[c];
        while (l < r) {
            int mid = (l + r) / 2;
            if (pos[c][mid] > cur) r = mid;
            else l = mid + 1;
        }

        if (l < sz[c]) {
            cur = pos[c][l];
            ans++;
        } else {
            ans += (n - 1 - cur);
            ans += 1;
            cur = -1;

            l = 0; r = sz[c];
            while (l < r) {
                int mid = (l + r) / 2;
                if (pos[c][mid] > cur) r = mid;
                else l = mid + 1;
            }
            cur = pos[c][l];
            ans += cur + 1;
        }
    }

    printf("%lld\n", ans);
    for (int c = 0; c < 26; c++) free(pos[c]);
    return 0;
}

