int main() {
    string s, t;
    cin >> s >> t;

    int n = s.size();
    int m = t.size();

    // Precompute next occurrence of each character from each position in s
    // next_pos[j][c] = next position >= j where s has character c
    // If not found, -1

    // For efficiency, precompute for each position j in s and each char c,
    // the next occurrence
    vector<array<int,26>> nxt(n+1);
    // nxt[j][c] = smallest index >= j in s where s[index] == c, or -1
    for(int c = 0; c < 26; c++) nxt[n][c] = -1;
    for(int j = n-1; j >= 0; j--) {
        for(int c = 0; c < 26; c++) nxt[j][c] = nxt[j+1][c];
        nxt[j][s[j]-'a'] = j;
    }

    long long reps = 0;
    int j = 0; // current position in s

    for(int k = 0; k < m; k++) {
        int c = t[k] - 'a';
        if(nxt[0][c] == -1) {
            // character not in s at all
            cout << -1 << endl;
            return 0;
        }
        if(nxt[j][c] != -1) {
            // found in current repetition
            j = nxt[j][c] + 1;
            if(j == n) { j = 0; reps++; }
        } else {
            // need to go to next repetition
            reps++;
            j = nxt[0][c] + 1;
            if(j == n) { j = 0; reps++; }
        }
    }

    long long ans = reps * n + j;
    cout << ans << endl;
    return 0;
}

