public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String s = sc.nextLine();
        String t = sc.nextLine();
        int n = s.length();

        // nextPos[c][i] = next occurrence of character c at or after index i in s (cyclically)
        int[][] nextPos = new int[26][n];
        int[] last = new int[26];
        Arrays.fill(last, -1);

        // Fill from the end to handle wrap-around
        for (int i = n - 1; i >= 0; i--) {
            last[s.charAt(i) - 'a'] = i;
            for (int c = 0; c < 26; c++) {
                nextPos[c][i] = last[c];
            }
        }

        long totalLen = 0;
        int idx = 0;
        long times = 1;

        for (char ch : t.toCharArray()) {
            int c = ch - 'a';
            if (last[c] == -1) {
                System.out.println(-1);
                return;
            }
            int nxt = nextPos[c][idx];
            if (nxt == -1) {
                // wrap around to next cycle
                times++;
                idx = nextPos[c][0] + 1;
            } else {
                idx = nxt + 1;
            }
            if (idx == n) {
                if (ch != t.charAt(t.length() - 1)) {
                    times++;
                    idx = 0;
                }
            }
        }

        long answer = (times - 1) * (long) n + idx;
        System.out.println(answer);
    }
}

