public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String s = br.readLine().trim();
        String t = br.readLine().trim();

        int n = s.length();
        int m = t.length();

        // next[i][c] = smallest index >= i in s where character c appears, or -1 if none
        // Also next[n][c] = first occurrence of c in s (for wrap-around)
        int[][] next = new int[n + 1][26];

        // Fill from right to left
        Arrays.fill(next[n], -1);
        for (int c = 0; c < 26; c++) {
            next[n][c] = -1;
        }

        for (int i = n - 1; i >= 0; i--) {
            for (int c = 0; c < 26; c++) {
                next[i][c] = next[i + 1][c];
            }
            next[i][s.charAt(i) - 'a'] = i;
        }

        long totalChars = 0;
        int posInS = 0; // current position in s

        for (int j = 0; j < m; j++) {
            int c = t.charAt(j) - 'a';

            if (next[0][c] == -1) {
                // Character doesn't exist in s at all
                System.out.println(-1);
                return;
            }

            if (next[posInS][c] != -1) {
                // Found in current copy
                int newPos = next[posInS][c];
                totalChars += (newPos - posInS + 1);
                posInS = newPos + 1;
                if (posInS == n) {
                    posInS = 0;
                    // totalChars already counted
                }
            } else {
                // Need to go to next copy
                // Skip remaining of current copy
                totalChars += (n - posInS);
                posInS = 0;
                // Now find in new copy starting from 0
                int newPos = next[0][c];
                totalChars += (newPos + 1);
                posInS = newPos + 1;
                if (posInS == n) {
                    posInS = 0;
                }
            }
        }

        System.out.println(totalChars);
    }
}

import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        String s = fs.next();
        String t = fs.next();

        int n = s.length();

        // Positions of each character in s
        ArrayList<Integer>[] pos = new ArrayList[26];
        for (int i = 0; i < 26; i++) pos[i] = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            pos[s.charAt(i) - 'a'].add(i);
        }

        // If some character in t does not exist in s, impossible
        for (int i = 0; i < t.length(); i++) {
            if (pos[t.charAt(i) - 'a'].isEmpty()) {
                System.out.println(-1);
                return;
            }
        }

        long loops = 0;   // how many full copies of s have been passed
        int cur = -1;     // current position inside current copy of s

        for (int i = 0; i < t.length(); i++) {
            int c = t.charAt(i) - 'a';
            ArrayList<Integer> list = pos[c];

            int idx = upperBound(list, cur); // first position > cur
            if (idx == list.size()) {
                // need next copy of s
                loops++;
                cur = list.get(0);
            } else {
                cur = list.get(idx);
            }
        }

        long answer = loops * n + (cur + 1L);
        System.out.println(answer);
    }

    // first index such that list.get(index) > x
    static int upperBound(ArrayList<Integer> list, int x) {
        int l = 0, r = list.size();
        while (l < r) {
            int m = (l + r) >>> 1;
            if (list.get(m) <= x) l = m + 1;
            else r = m;
        }
        return l;
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
            } while (c != -1 && c <= ' ');
            while (c != -1 && c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }
    }
}
